import{_ as a,o as t,c as r,a2 as n}from"./chunks/framework.Cc8dJFaW.js";const u=JSON.parse('{"title":"2026-11-20 Agent Research and Competitive Intelligence","description":"","frontmatter":{"title":"2026-11-20 Agent Research and Competitive Intelligence","outline":[2,3]},"headers":[],"relativePath":"en/runtime/daily-intelligence/2026-11-20.md","filePath":"en/runtime/daily-intelligence/2026-11-20.md","lastUpdated":null}'),i={name:"en/runtime/daily-intelligence/2026-11-20.md"};function s(o,e,l,d,c,p){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="_2026-11-20-agent-research-and-competitive-intelligence" tabindex="-1">2026-11-20 Agent Research and Competitive Intelligence <a class="header-anchor" href="#_2026-11-20-agent-research-and-competitive-intelligence" aria-label="Permalink to &quot;2026-11-20 Agent Research and Competitive Intelligence&quot;">​</a></h1><p>Core: the merged MCP Events text is Final, while event wakeup still needs authorization, deduplication and gap reconciliation. Employee delivery separates run success, artifact saving and stream durability. Yesterday’s seven pending groups are reconciled by original date/ID rather than replaced by today’s A numbers.</p><p>Started 2026-11-20 11:18:05 Asia/Shanghai. Fresh main Registry: 47 researchers, 88 original repository entries; baseline run 2026-11-19T024709Z. Event dates are UTC. 31 external observations, five analyses and seven carryover items; zero new local experiments, articles, formal reviews or development assignments today.</p><h2 id="reconciliation-of-previous-pending-work" tabindex="-1">Reconciliation of previous pending work <a class="header-anchor" href="#reconciliation-of-previous-pending-work" aria-label="Permalink to &quot;Reconciliation of previous pending work&quot;">​</a></h2><p>Sources are the <a href="./2026-11-19">November 19 report</a>. Reconciled November 20 against yesterday’s <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/manual-runs/2026-11-19-skill-side-effects/00-report.md" target="_blank" rel="noreferrer">independent experiment report</a> and published bilingual article (<a href="/joinwell52/zh/research/2026-11-19-skill-says-read-only">Chinese</a>, <a href="/joinwell52/en/research/2026-11-19-skill-says-read-only">English</a>). These followed yesterday’s monitoring snapshot: do not rewrite it or count them as today’s new work. No real file write, complete approval or live skill-mounting validation was performed.</p><table tabindex="0"><thead><tr><th>Source date + original ID</th><th>Reconciliation</th><th>Scope, remaining work and evidence</th></tr></thead><tbody><tr><td>2026-11-19 A1</td><td>Partially completed; remaining pending</td><td>A separate November 19 study ran 13 upstream tests, six synthetic assertions, three CodeFlowMu schema and six operation-fact assertions. Reconciled November 20 from the published report; not rerun today. O2–O6, live skill mounting and end-to-end authority/execution remain pending.</td></tr><tr><td>2026-11-19 A2</td><td>Pending</td><td>Schema/operation-fact probes do not replace fork, revocation or caller-identity tests; today adds upstream policy-refresh evidence only.</td></tr><tr><td>2026-11-19 A3</td><td>Pending</td><td>Three-role dispatch/consumption/acceptance and external-delivery experiments were not run; managed private-PR identity evidence refines cases.</td></tr><tr><td>2026-11-19 A4</td><td>Pending</td><td>No local full-disk, lock-sweep, idle-death or executor fault replay; new recovery/backpressure fixes are comparison material. Yesterday&#39;s O27 #9539 closed unmerged; successor #9574 remains OPEN.</td></tr><tr><td>2026-11-19 A5</td><td>Reference retained; validation pending</td><td>Restart/multi-process memory and user-budget trials were not run; nested Flow state changes add comparison evidence only.</td></tr><tr><td>2026-11-19 A6</td><td>Document review advanced; experiments pending</td><td>MCP Events and message contracts reviewed; duplicate/reordering/disconnect replay experiments remain unrun.</td></tr><tr><td>2026-11-19 A7</td><td>Pending</td><td>No complete installation, phone/Windows upgrade, signing or rollback acceptance. Releases do not substitute for trials; Orca licensing gap remains.</td></tr></tbody></table><h2 id="factual-observations" tabindex="-1">Factual observations <a class="header-anchor" href="#factual-observations" aria-label="Permalink to &quot;Factual observations&quot;">​</a></h2><p><span id="o1"></span></p><h3 id="o1-mcp-events-extension-is-final-in-the-merged-specification" tabindex="-1">O1 MCP Events Extension is Final in the merged specification <a class="header-anchor" href="#o1-mcp-events-extension-is-final-in-the-merged-specification" aria-label="Permalink to &quot;O1 MCP Events Extension is Final in the merged specification&quot;">​</a></h3><p>MERGED November 19, #3415. The merged text explicitly says Final for io.modelcontextprotocol/events; stale PR sketch/0000 prose is not the final artifact. Event types select optional poll/stream/signed-webhook modes. Opaque cursors, optional replay and truncated gap notices are distinct; eventId deduplication is subscription-scoped. Payloads remain untrusted under MCP principal authorization. Final status does not establish SDK/server deployment maturity.</p><p>Evidence and status: <a href="https://github.com/modelcontextprotocol/modelcontextprotocol/pull/3415" target="_blank" rel="noreferrer">MERGED · 2026-11-19T15:06:35Z</a> · <a href="https://github.com/modelcontextprotocol/modelcontextprotocol/blob/8a18b4b3292b9f9b3aee73f6325f9f62f19a89f9/seps/3415-events-extension.md" target="_blank" rel="noreferrer">FINAL_SPEC_TEXT · 2026-11-19</a></p><p><span id="o2"></span></p><h3 id="o2-codex-applies-refreshed-policy-to-running-threads" tabindex="-1">O2 Codex applies refreshed policy to running threads <a class="header-anchor" href="#o2-codex-applies-refreshed-policy-to-running-threads" aria-label="Permalink to &quot;O2 Codex applies refreshed policy to running threads&quot;">​</a></h3><p>MERGED November 19, #62585/#62614. Running threads accept restrictions even when the current model becomes disallowed, queueing automatic work until permitted or replaced. Source changes before publication/live-thread rejection error. Config reload/login/logout refresh policy despite unrelated load failures; late low-risk scores cannot relax stricter approval requirements.</p><p>Evidence and status: <a href="https://github.com/openai/codex/pull/62585" target="_blank" rel="noreferrer">MERGED · 2026-11-19T20:26:34Z</a> · <a href="https://github.com/openai/codex/pull/62614" target="_blank" rel="noreferrer">MERGED · 2026-11-19T22:32:19Z</a></p><p><span id="o3"></span></p><h3 id="o3-codex-backpressures-resumed-requests-and-rechecks-approval-eligibility" tabindex="-1">O3 Codex backpressures resumed requests and rechecks approval eligibility <a class="header-anchor" href="#o3-codex-backpressures-resumed-requests-and-rechecks-approval-eligibility" aria-label="Permalink to &quot;O3 Codex backpressures resumed requests and rechecks approval eligibility&quot;">​</a></h3><p>MERGED November 19, #62609. After thread/resume responds, pending requests replay in background one write receipt at a time per connection. Each send rechecks pending state and human-approval eligibility. New resume replaces replay; unsubscribe/disconnect stops it. Resume is not unconditional resend.</p><p>Evidence and status: <a href="https://github.com/openai/codex/pull/62609" target="_blank" rel="noreferrer">MERGED · 2026-11-19T22:15:58Z</a></p><p><span id="o4"></span></p><h3 id="o4-codex-frees-tool-results-only-with-exact-durable-copies" tabindex="-1">O4 Codex frees tool results only with exact durable copies <a class="header-anchor" href="#o4-codex-frees-tool-results-only-with-exact-durable-copies" aria-label="Permalink to &quot;O4 Codex frees tool results only with exact durable copies&quot;">​</a></h3><p>MERGED November 20, #62641. Successful MCP results in persisted paginated threads leave active-turn memory only after exact stored matching. Resume reads by item ID rather than stale history pages. Truncated/missing/mismatched/failed results stay resident. Memory reduction is conditional on recoverability.</p><p>Evidence and status: <a href="https://github.com/openai/codex/pull/62641" target="_blank" rel="noreferrer">MERGED · 2026-11-20T01:49:46Z</a></p><p><span id="o5"></span></p><h3 id="o5-codex-separates-thread-retention-from-inheritance-and-preemption" tabindex="-1">O5 Codex separates thread retention from inheritance and preemption <a class="header-anchor" href="#o5-codex-separates-thread-retention-from-inheritance-and-preemption" aria-label="Permalink to &quot;O5 Codex separates thread retention from inheritance and preemption&quot;">​</a></h3><p>MERGED November 20, #62654/#62639. alwaysInThread retains across windows without child inheritance; alwaysInChildren controls child transfer, while always covers both. Tool calls/results must remain adjacent with matching retention. Queue-only mail waits after a retained final answer, while user steering can reopen the turn. Context transfer does not establish authority transfer.</p><p>Evidence and status: <a href="https://github.com/openai/codex/pull/62654" target="_blank" rel="noreferrer">MERGED · 2026-11-20T03:00:31Z</a> · <a href="https://github.com/openai/codex/pull/62639" target="_blank" rel="noreferrer">MERGED · 2026-11-20T01:36:08Z</a></p><p><span id="o6"></span></p><h3 id="o6-codex-preserves-exit-evidence-across-concurrent-state-updates" tabindex="-1">O6 Codex preserves exit evidence across concurrent state updates <a class="header-anchor" href="#o6-codex-preserves-exit-evidence-across-concurrent-state-updates" aria-label="Permalink to &quot;O6 Codex preserves exit evidence across concurrent state updates&quot;">​</a></h3><p>MERGED November 19, #62557. Lifecycle transitions update under the write lock instead of replacing snapshots, preserving exit code, sandbox denial and first failure across rejected stdin/termination updates. This fixes terminal-evidence consistency, not proof that every process stopped.</p><p>Evidence and status: <a href="https://github.com/openai/codex/pull/62557" target="_blank" rel="noreferrer">MERGED · 2026-11-19T17:34:01Z</a></p><p><span id="o7"></span></p><h3 id="o7-codex-correlates-child-lifecycle-attempts-without-conflating-stop-acceptance" tabindex="-1">O7 Codex correlates child lifecycle attempts without conflating stop acceptance <a class="header-anchor" href="#o7-codex-correlates-child-lifecycle-attempts-without-conflating-stop-acceptance" aria-label="Permalink to &quot;O7 Codex correlates child lifecycle attempts without conflating stop acceptance&quot;">​</a></h3><p>MERGED November 19, #62567. Spawn/accepted close/interrupt and initial/follow-up/resumed turn attempts are correlated by thread/turn/call IDs, with at most one outcome per attempt and no high-cardinality ID metric labels. Accepted stops count even for idle targets, so counters are not exit proof.</p><p>Evidence and status: <a href="https://github.com/openai/codex/pull/62567" target="_blank" rel="noreferrer">MERGED · 2026-11-19T18:40:07Z</a></p><p><span id="o8"></span></p><h3 id="o8-codex-0-171-ships-with-distinct-release-boundaries" tabindex="-1">O8 Codex 0.171 ships with distinct release boundaries <a class="header-anchor" href="#o8-codex-0-171-ships-with-distinct-release-boundaries" aria-label="Permalink to &quot;O8 Codex 0.171 ships with distinct release boundaries&quot;">​</a></h3><p>rust-v0.171.0 was released in this window, delivering earlier remote noninteractive exec, child transcripts and recovery work. Count delivery status, not old merges again; packaging of later policy/memory/retention changes must be checked separately.</p><p>Evidence and status: <a href="https://github.com/openai/codex/releases/tag/rust-v0.171.0" target="_blank" rel="noreferrer">RELEASED · 2026-11-20T00:44:47Z</a></p><p><span id="o9"></span></p><h3 id="o9-paperclip-verifies-delivery-with-the-run-s-authorized-github-identity" tabindex="-1">O9 Paperclip verifies delivery with the run&#39;s authorized GitHub identity <a class="header-anchor" href="#o9-paperclip-verifies-delivery-with-the-run-s-authorized-github-identity" aria-label="Permalink to &quot;O9 Paperclip verifies delivery with the run&#39;s authorized GitHub identity&quot;">​</a></h3><p>MERGED November 19, #22357, extending yesterday&#39;s O28. Background credentials could not use the managed identity that merged a private PR. Verification now binds current grants/membership/trust to company/task/run, including succeeded-run reassessment and steering settlement under locks. GitHub still independently confirms merge. High delivery-governance learning/attention; main radar unchanged.</p><p>Evidence and status: <a href="https://github.com/paperclipai/paperclip/pull/22357" target="_blank" rel="noreferrer">MERGED · 2026-11-19T22:44:04Z</a></p><p><span id="o10"></span></p><h3 id="o10-paperclip-keeps-execution-held-tasks-blocked" tabindex="-1">O10 Paperclip keeps execution-held tasks blocked <a class="header-anchor" href="#o10-paperclip-keeps-execution-held-tasks-blocked" aria-label="Permalink to &quot;O10 Paperclip keeps execution-held tasks blocked&quot;">​</a></h3><p>MERGED November 19, #22245. Agent status/reopen/resume/checkout requests cannot move an execution-held task out of Blocked; 409 explains the required resolution. Previously actionable-looking tasks remained inadmissible and schedules spun. High learning value for alignment of displayed state and admission.</p><p>Evidence and status: <a href="https://github.com/paperclipai/paperclip/pull/22245" target="_blank" rel="noreferrer">MERGED · 2026-11-19T20:37:58Z</a></p><p><span id="o11"></span></p><h3 id="o11-paperclip-negotiates-next-run-identity-after-restart" tabindex="-1">O11 Paperclip negotiates next-run identity after restart <a class="header-anchor" href="#o11-paperclip-negotiates-next-run-identity-after-restart" aria-label="Permalink to &quot;O11 Paperclip negotiates next-run identity after restart&quot;">​</a></h3><p>MERGED November 19, #22343. Providers advertising resumeIdentityVersion:1 restart released warm tasks directly as the next run even after Core restart, avoiding old-run-then-handoff. Conditional negotiation is not universal provider support. High identity/recovery learning value; main radar retained.</p><p>Evidence and status: <a href="https://github.com/paperclipai/paperclip/pull/22343" target="_blank" rel="noreferrer">MERGED · 2026-11-19T19:20:49Z</a></p><p><span id="o12"></span></p><h3 id="o12-paperclip-drives-execution-evidence-migration-during-online-preparation" tabindex="-1">O12 Paperclip drives execution-evidence migration during online preparation <a class="header-anchor" href="#o12-paperclip-drives-execution-evidence-migration-during-online-preparation" aria-label="Permalink to &quot;O12 Paperclip drives execution-evidence migration during online preparation&quot;">​</a></h3><p>MERGED November 19, #22337. Online preparation drives bounded log/provider-trace pages with separate cursors/shared owners and owner_busy signals, retaining canceled transfers until settlement. Unproven canonical coverage/active sources stay blocked. High learning value; past background scans do not establish safe volume removal.</p><p>Evidence and status: <a href="https://github.com/paperclipai/paperclip/pull/22337" target="_blank" rel="noreferrer">MERGED · 2026-11-19T18:28:06Z</a></p><p><span id="o13"></span></p><h3 id="o13-paperclip-retries-audit-inserts-rather-than-connector-actions" tabindex="-1">O13 Paperclip retries audit inserts rather than connector actions <a class="header-anchor" href="#o13-paperclip-retries-audit-inserts-rather-than-connector-actions" aria-label="Permalink to &quot;O13 Paperclip retries audit inserts rather than connector actions&quot;">​</a></h3><p>MERGED November 19, #22329. Only audit inserts retry boundedly for three contention codes, up to five attempts; other errors fail. The deadlock victim statement rolls back, avoiding duplicate audit rows. This does not replay the whole connector call. Upstream real-database regression, not locally reproduced. High recovery learning value.</p><p>Evidence and status: <a href="https://github.com/paperclipai/paperclip/pull/22329" target="_blank" rel="noreferrer">MERGED · 2026-11-19T18:23:22Z</a></p><p><span id="o14"></span></p><h3 id="o14-paperclip-delegates-reversible-responsibilities-and-routine-changes" tabindex="-1">O14 Paperclip delegates reversible responsibilities and routine changes <a class="header-anchor" href="#o14-paperclip-delegates-reversible-responsibilities-and-routine-changes" aria-label="Permalink to &quot;O14 Paperclip delegates reversible responsibilities and routine changes&quot;">​</a></h3><p>MERGED November 19, #22261/#22274. Under experimental responsibilities, agents modify their person&#39;s areas/responsibilities/routines with versioned undo, while permanent deletion needs a confirmation card and authority follows the responsible user. High employee-product learning/attention; main radar unchanged, no organizational trial.</p><p>Evidence and status: <a href="https://github.com/paperclipai/paperclip/pull/22261" target="_blank" rel="noreferrer">MERGED · 2026-11-19T15:29:12Z</a> · <a href="https://github.com/paperclipai/paperclip/pull/22274" target="_blank" rel="noreferrer">MERGED · 2026-11-19T15:30:04Z</a></p><p><span id="o15"></span></p><h3 id="o15-paperclip-preserves-policy-relevant-names-while-narrowing-catalog-reads" tabindex="-1">O15 Paperclip preserves policy-relevant names while narrowing catalog reads <a class="header-anchor" href="#o15-paperclip-preserves-policy-relevant-names-while-narrowing-catalog-reads" aria-label="Permalink to &quot;O15 Paperclip preserves policy-relevant names while narrowing catalog reads&quot;">​</a></h3><p>MERGED November 19, #22356. Instruction catalog reads narrow to candidates while retaining short-ID naming peers in the snapshot, assigning names before filtering so optimization cannot change authorization matches. High learning value for policy-relevant naming; existing grants/trust remain.</p><p>Evidence and status: <a href="https://github.com/paperclipai/paperclip/pull/22356" target="_blank" rel="noreferrer">MERGED · 2026-11-19T22:07:48Z</a></p><p><span id="o16"></span></p><h3 id="o16-orca-exposes-worker-approvals-in-the-phone-coordinator-chat" tabindex="-1">O16 Orca exposes worker approvals in the phone coordinator chat <a class="header-anchor" href="#o16-orca-exposes-worker-approvals-in-the-phone-coordinator-chat" aria-label="Permalink to &quot;O16 Orca exposes worker approvals in the phone coordinator chat&quot;">​</a></h3><p>MERGED November 20, #44942. Structured phone coordinator chats display oldest worker approvals when no own question is pending, gated by the host paired-worker-approvals.v1 capability. Versioned approvalAnswer handles decisions and streams reconnect. High mobile-governance learning/attention; second circle retained, no phone acceptance test.</p><p>Evidence and status: <a href="https://github.com/stablyai/orca/pull/44942" target="_blank" rel="noreferrer">MERGED · 2026-11-20T03:10:00Z</a></p><p><span id="o17"></span></p><h3 id="o17-orca-bots-release-expands-managed-session-identity-and-tools" tabindex="-1">O17 Orca Bots release expands managed session identity and tools <a class="header-anchor" href="#o17-orca-bots-release-expands-managed-session-identity-and-tools" aria-label="Permalink to &quot;O17 Orca Bots release expands managed session identity and tools&quot;">​</a></h3><p>v1.4.265 RELEASED in this window. Upstream claims broader managed-session tools/identity, owner-represented sharing and real-address Gmail matching. Auto-update defaults off and waits around active terminals; phone compatibility has version boundaries. High employee-product learning/attention, second circle unchanged; full authority/commercial/license boundaries were not independently validated.</p><p>Evidence and status: <a href="https://github.com/stablyai/orca/releases/tag/v1.4.265" target="_blank" rel="noreferrer">RELEASED · 2026-11-19T23:41:51Z</a></p><p><span id="o18"></span></p><h3 id="o18-orca-avoids-dpkg-updates-for-repackaged-linux-installs" tabindex="-1">O18 Orca avoids dpkg updates for repackaged Linux installs <a class="header-anchor" href="#o18-orca-avoids-dpkg-updates-for-repackaged-linux-installs" aria-label="Permalink to &quot;O18 Orca avoids dpkg updates for repackaged Linux installs&quot;">​</a></h3><p>MERGED November 20, #45067. Deb self-update also requires dpkg&#39;s orca-ide package list, treating repackaged installations as externally managed to avoid overwriting another manager&#39;s files. Medium-high delivery learning value, not signing/rollback acceptance.</p><p>Evidence and status: <a href="https://github.com/stablyai/orca/pull/45067" target="_blank" rel="noreferrer">MERGED · 2026-11-20T02:29:58Z</a></p><p><span id="o19"></span></p><h3 id="o19-crewai-ships-versioned-artifacts-with-best-effort-save-semantics" tabindex="-1">O19 CrewAI ships versioned artifacts with best-effort save semantics <a class="header-anchor" href="#o19-crewai-ships-versioned-artifacts-with-best-effort-save-semantics" aria-label="Permalink to &quot;O19 CrewAI ships versioned artifacts with best-effort save semantics&quot;">​</a></h3><p>MERGED November 19, #9551, shipped in 1.15.44. Artifacts have identifiers, versions, pre-upload UUIDs and creation events; concurrent saves do not overwrite and callbacks see links. Save failure only warns without failing the run. High learning value for delivery contracts; run success does not establish artifact delivery.</p><p>Evidence and status: <a href="https://github.com/crewAIInc/crewAI/pull/9551" target="_blank" rel="noreferrer">MERGED · 2026-11-19T13:10:09Z</a> · <a href="https://github.com/crewAIInc/crewAI/releases/tag/1.15.44" target="_blank" rel="noreferrer">RELEASED · 2026-11-19T17:59:49Z</a></p><p><span id="o20"></span></p><h3 id="o20-crewai-deep-copies-nested-flow-defaults-with-a-fallback" tabindex="-1">O20 CrewAI deep-copies nested Flow defaults with a fallback <a class="header-anchor" href="#o20-crewai-deep-copies-nested-flow-defaults-with-a-fallback" aria-label="Permalink to &quot;O20 CrewAI deep-copies nested Flow defaults with a fallback&quot;">​</a></h3><p>MERGED/RELEASED November 19, #9527. Deep-copy isolates nested declared Flow defaults formerly shared through dict(); uncopyable values still fall back to dict(), so arbitrary custom objects are not universally isolated. Run identity and mutable-state isolation are separate checks.</p><p>Evidence and status: <a href="https://github.com/crewAIInc/crewAI/pull/9527" target="_blank" rel="noreferrer">MERGED · 2026-11-19T13:32:49Z</a> · <a href="https://github.com/crewAIInc/crewAI/releases/tag/1.15.44" target="_blank" rel="noreferrer">RELEASED · 2026-11-19T17:59:49Z</a></p><p><span id="o21"></span></p><h3 id="o21-crewai-fixes-symlink-containment-with-explicit-scope-limits" tabindex="-1">O21 CrewAI fixes symlink containment with explicit scope limits <a class="header-anchor" href="#o21-crewai-fixes-symlink-containment-with-explicit-scope-limits" aria-label="Permalink to &quot;O21 CrewAI fixes symlink containment with explicit scope limits&quot;">​</a></h3><p>MERGED November 19, #9569. Resolved path containment fixes parent-symlink and string-prefix bypasses. Plain outside-cwd absolute paths without symlinks remain allowed by declared compatibility scope; this is not universal cwd confinement.</p><p>Evidence and status: <a href="https://github.com/crewAIInc/crewAI/pull/9569" target="_blank" rel="noreferrer">MERGED · 2026-11-19T06:08:20Z</a></p><p><span id="o22"></span></p><h3 id="o22-crewai-timeout-proposal-closes-unmerged-successor-remains-open" tabindex="-1">O22 CrewAI timeout proposal closes unmerged; successor remains open <a class="header-anchor" href="#o22-crewai-timeout-proposal-closes-unmerged-successor-remains-open" aria-label="Permalink to &quot;O22 CrewAI timeout proposal closes unmerged; successor remains open&quot;">​</a></h3><p>Updates November 19 O27: #9539 closed unmerged on November 19 after conflicts and was superseded by #9574. The successor remains OPEN for kickoff/kickoff_async/akickoff; its author still reports unrun local tests. Closure is not completion, nor proof this shipped in 1.15.44.</p><p>Evidence and status: <a href="https://github.com/crewAIInc/crewAI/pull/9539" target="_blank" rel="noreferrer">CLOSED_UNMERGED · 2026-11-19T16:03:34Z</a> · <a href="https://github.com/crewAIInc/crewAI/pull/9574" target="_blank" rel="noreferrer">OPEN · 2026-11-19T16:03:29Z</a></p><p><span id="o23"></span></p><h3 id="o23-langgraph-aligns-send-tool-state-with-edge-dispatched-state" tabindex="-1">O23 LangGraph aligns Send tool state with edge-dispatched state <a class="header-anchor" href="#o23-langgraph-aligns-send-tool-state-with-edge-dispatched-state" aria-label="Permalink to &quot;O23 LangGraph aligns Send tool state with edge-dispatched state&quot;">​</a></h3><p>MERGED November 19, #9728. Bare-list Send tool calls now read schema-coerced graph state, including managed values, like edge dispatch rather than raw channel dicts. Distinct from yesterday&#39;s wrapper-override issue; not locally regression-tested.</p><p>Evidence and status: <a href="https://github.com/langchain-ai/langgraph/pull/9728" target="_blank" rel="noreferrer">MERGED · 2026-11-19T04:55:30Z</a></p><p><span id="o24"></span></p><h3 id="o24-langgraph-repairs-clear-all-and-null-checkpoint-replay-semantics" tabindex="-1">O24 LangGraph repairs clear-all and null-checkpoint replay semantics <a class="header-anchor" href="#o24-langgraph-repairs-clear-all-and-null-checkpoint-replay-semantics" aria-label="Permalink to &quot;O24 LangGraph repairs clear-all and null-checkpoint replay semantics&quot;">​</a></h3><p>MERGED November 19, #9735. REMOVE_ALL_MESSAGES clears state and prior writes in the batch; null checkpoints restore an empty channel instead of passing None into reducers. A shared reducer can support stable downstream IDs, without proving downstream migration completed.</p><p>Evidence and status: <a href="https://github.com/langchain-ai/langgraph/pull/9735" target="_blank" rel="noreferrer">MERGED · 2026-11-19T23:08:18Z</a></p><p><span id="o25"></span></p><h3 id="o25-langchain-recovers-interleaved-streamed-tool-arguments-by-item-id" tabindex="-1">O25 LangChain recovers interleaved streamed tool arguments by item ID <a class="header-anchor" href="#o25-langchain-recovers-interleaved-streamed-tool-arguments-by-item-id" aria-label="Permalink to &quot;O25 LangChain recovers interleaved streamed tool arguments by item ID&quot;">​</a></h3><p>MERGED November 19, #41963, in langchain-openai 1.8.5. Missing argument suffixes are recovered from done/final snapshots by item ID without duplicate or interleaved arguments. Pre-action checks need final arguments, not partial deltas. No live-model reproduction.</p><p>Evidence and status: <a href="https://github.com/langchain-ai/langchain/pull/41963" target="_blank" rel="noreferrer">MERGED · 2026-11-19T23:01:03Z</a> · <a href="https://github.com/langchain-ai/langchain/releases/tag/langchain-openai%3D%3D1.8.5" target="_blank" rel="noreferrer">RELEASED · 2026-11-19T23:16:20Z</a></p><p><span id="o26"></span></p><h3 id="o26-github-mcp-completes-resource-paths-against-the-pr-head" tabindex="-1">O26 GitHub MCP completes resource paths against the PR head <a class="header-anchor" href="#o26-github-mcp-completes-resource-paths-against-the-pr-head" aria-label="Permalink to &quot;O26 GitHub MCP completes resource paths against the PR head&quot;">​</a></h3><p>MERGED November 19, #3860. PR-head resource completions use the PR tree rather than default branch, avoiding missing new/deleted-path suggestions. Invalid PR numbers fail before API access. Useful artifact-version consistency; merge does not establish released server deployment.</p><p>Evidence and status: <a href="https://github.com/github/github-mcp-server/pull/3860" target="_blank" rel="noreferrer">MERGED · 2026-11-19T18:44:50Z</a></p><p><span id="o27"></span></p><h3 id="o27-langfuse-repairs-and-constrains-role-assignment-drift" tabindex="-1">O27 Langfuse repairs and constrains role-assignment drift <a class="header-anchor" href="#o27-langfuse-repairs-and-constrains-role-assignment-drift" aria-label="Permalink to &quot;O27 Langfuse repairs and constrains role-assignment drift&quot;">​</a></h3><p>MERGED November 19, #20234. Migration repairs stale/orphan assignments and cross-organization memberships, adding deferred constraints/drift checks while retaining tagged/expiring grants. Authorizing sessions from assignments is follow-up work, not a completed whole-RBAC cutover.</p><p>Evidence and status: <a href="https://github.com/langfuse/langfuse/pull/20234" target="_blank" rel="noreferrer">MERGED · 2026-11-19T18:21:25Z</a></p><p><span id="o28"></span></p><h3 id="o28-openhands-classifies-orphan-tool-messages-for-history-recovery" tabindex="-1">O28 OpenHands classifies orphan tool messages for history recovery <a class="header-anchor" href="#o28-openhands-classifies-orphan-tool-messages-for-history-recovery" aria-label="Permalink to &quot;O28 OpenHands classifies orphan tool messages for history recovery&quot;">​</a></h3><p>MERGED November 20, #6678. Provider errors for orphan/duplicate/out-of-order tool history classify as LLMMalformedConversationHistoryError and enter existing condensation recovery instead of generic bad request. Classification does not prove condensation preserves all authority/effect evidence.</p><p>Evidence and status: <a href="https://github.com/OpenHands/software-agent-sdk/pull/6678" target="_blank" rel="noreferrer">MERGED · 2026-11-20T01:16:29Z</a></p><p><span id="o29"></span></p><h3 id="o29-openhands-sdk-1-63-ships-with-experimental-feature-boundaries" tabindex="-1">O29 OpenHands SDK 1.63 ships with experimental feature boundaries <a class="header-anchor" href="#o29-openhands-sdk-1-63-ships-with-experimental-feature-boundaries" aria-label="Permalink to &quot;O29 OpenHands SDK 1.63 ships with experimental feature boundaries&quot;">​</a></h3><p>v1.63.0 RELEASED in this window, including opt-in experimental-feature infrastructure, reactions and earlier client work. Delivery status is new; later merges or a judge without a caller are not assumed effective in the product. Not installed/tested locally.</p><p>Evidence and status: <a href="https://github.com/OpenHands/software-agent-sdk/releases/tag/v1.63.0" target="_blank" rel="noreferrer">RELEASED · 2026-11-19T19:07:57Z</a></p><p><span id="o30"></span></p><h3 id="o30-ag2-1-3-3-exposes-sdk-transport-migration-choices" tabindex="-1">O30 AG2 1.3.3 exposes SDK transport migration choices <a class="header-anchor" href="#o30-ag2-1-3-3-exposes-sdk-transport-migration-choices" aria-label="Permalink to &quot;O30 AG2 1.3.3 exposes SDK transport migration choices&quot;">​</a></h3><p>v1.3.3 RELEASED, allowing google-genai 3.x. Developer API default changes from v1beta to v1, requiring explicit versions for some latest/preview aliases. Default HTTP transport changes to httpx2 with client configuration implications. Similar generation APIs do not remove migration checks; no local upgrade.</p><p>Evidence and status: <a href="https://github.com/ag2ai/ag2/releases/tag/v1.3.3" target="_blank" rel="noreferrer">RELEASED · 2026-11-19T20:30:48Z</a></p><p><span id="o31"></span></p><h3 id="o31-adk-reverts-aggregated-streamed-persistence-without-last-chunk" tabindex="-1">O31 ADK reverts aggregated streamed persistence without last_chunk <a class="header-anchor" href="#o31-adk-reverts-aggregated-streamed-persistence-without-last-chunk" aria-label="Permalink to &quot;O31 ADK reverts aggregated streamed persistence without last_chunk&quot;">​</a></h3><p>Committed this window: RemoteA2aAgent no longer emits an aggregated event after partial artifacts because forwarding both duplicated client answers. Without last_chunk, streamed answers again are not persisted; a gated reintroduction is only planned. Check both display deduplication and session durability.</p><p>Evidence and status: <a href="https://github.com/google/adk-python/commit/5523aa7333d36736262b2e38d7a302f1505b1822" target="_blank" rel="noreferrer">COMMITTED · 2026-11-19T19:04:14Z</a></p><h2 id="research-analysis" tabindex="-1">Research analysis <a class="header-anchor" href="#research-analysis" aria-label="Permalink to &quot;Research analysis&quot;">​</a></h2><p><span id="a1"></span></p><h3 id="a1-final-event-semantics-still-need-task-admission-and-gap-handling" tabindex="-1">A1 Final event semantics still need task admission and gap handling <a class="header-anchor" href="#a1-final-event-semantics-still-need-task-admission-and-gap-handling" aria-label="Permalink to &quot;A1 Final event semantics still need task admission and gap handling&quot;">​</a></h3><p><a href="#o1">O1</a> · <a href="#o16">O16</a> · <a href="#o25">O25</a> · <a href="#o26">O26</a> · <a href="#o31">O31</a></p><p>Supported: Final MCP Events defines subscriptions, cursors, optional replay and gaps; Orca capability-gates mobile subscriptions. SDK/source/local consistency is unverified. Carry November 19 A6 forward: disconnect/duplicate/reordered/multiple-subscription replay remains unrun, testing subscription deduplication separately from task admission. Payload is not instruction/authority. Compare FCoP task/artifact/evidence contracts with complementary event transport. Costs: cursors, compensation and durable state. Topic: how does truncated identify tasks needing reconciliation?</p><p><span id="a2"></span></p><h3 id="a2-continuous-work-requires-refreshed-authority-and-reversible-role-changes" tabindex="-1">A2 Continuous work requires refreshed authority and reversible role changes <a class="header-anchor" href="#a2-continuous-work-requires-refreshed-authority-and-reversible-role-changes" aria-label="Permalink to &quot;A2 Continuous work requires refreshed authority and reversible role changes&quot;">​</a></h3><p><a href="#o2">O2</a> · <a href="#o9">O9</a> · <a href="#o10">O10</a> · <a href="#o14">O14</a> · <a href="#o15">O15</a> · <a href="#o16">O16</a> · <a href="#o17">O17</a> · <a href="#o21">O21</a> · <a href="#o27">O27</a></p><p>Supported: refreshed policy blocks old models, private-PR acceptance uses current managed identity, execution holds constrain mutations, and responsibilities/routines have owner/undo boundaries. November 19 A2 remains pending; operation-fact probes are not authority validation. Candidate: tighten policy mid-task, change identity after approval and mutate another user&#39;s routine, checking principal/version at execution. Compare CodeFlowMu role/SOP/action controls without moving account/credential/scheduling into FCoP. High enterprise learning/attention; no local defect established. Costs: versioning, lookups and human takeover.</p><p><span id="a3"></span></p><h3 id="a3-delivery-needs-independent-evidence-beyond-run-success-or-stop-counters" tabindex="-1">A3 Delivery needs independent evidence beyond run success or stop counters <a class="header-anchor" href="#a3-delivery-needs-independent-evidence-beyond-run-success-or-stop-counters" aria-label="Permalink to &quot;A3 Delivery needs independent evidence beyond run success or stop counters&quot;">​</a></h3><p><a href="#o4">O4</a> · <a href="#o6">O6</a> · <a href="#o7">O7</a> · <a href="#o9">O9</a> · <a href="#o12">O12</a> · <a href="#o13">O13</a> · <a href="#o19">O19</a> · <a href="#o22">O22</a> · <a href="#o23">O23</a> · <a href="#o24">O24</a> · <a href="#o25">O25</a> · <a href="#o26">O26</a> · <a href="#o28">O28</a> · <a href="#o31">O31</a></p><p>Supported: CrewAI artifact save only warns on failure while Paperclip requires external PR proof; ADK&#39;s deduplication revert restores a durability gap. November 19 A3&#39;s three-role experiment remains unrun. Candidate: failed upload, missing last_chunk, interleaved arguments, private-PR grant loss and retried audit inserts; compare run outcome, artifact version, save/receive receipts and acceptance. Audit retry is distinct from action replay. FCoP concerns identity/acceptance evidence; Runtime owns settlement. Costs: storage/authority fault fixtures and independent controls. Topic: who sees what when run success has no artifact?</p><p><span id="a4"></span></p><h3 id="a4-recovery-and-memory-optimization-depend-on-reconstructible-evidence" tabindex="-1">A4 Recovery and memory optimization depend on reconstructible evidence <a class="header-anchor" href="#a4-recovery-and-memory-optimization-depend-on-reconstructible-evidence" aria-label="Permalink to &quot;A4 Recovery and memory optimization depend on reconstructible evidence&quot;">​</a></h3><p><a href="#o3">O3</a> · <a href="#o4">O4</a> · <a href="#o5">O5</a> · <a href="#o6">O6</a> · <a href="#o8">O8</a> · <a href="#o10">O10</a> · <a href="#o11">O11</a> · <a href="#o12">O12</a> · <a href="#o18">O18</a> · <a href="#o20">O20</a> · <a href="#o22">O22</a> · <a href="#o24">O24</a> · <a href="#o28">O28</a> · <a href="#o29">O29</a> · <a href="#o30">O30</a></p><p>Supported: Codex frees only exactly recoverable results, replays by receipts and updates process state in place; Paperclip preserves next-run identity/evidence ownership. November 19 A4/A5 recovery and memory/budget trials remain pending. Candidates add truncated storage, stale pages, slow clients, unsettled cancellation, shallow-copy fallback and SDK defaults. Accepted stops are not exits; a closed-unmerged timeout PR is not a fix. Compare recovery receipts at FCoP; memory/pools/leases/installation belong to Runtime/product. Costs: fault injection and versioned environments.</p><p><span id="a5"></span></p><h3 id="a5-reconcile-the-skill-study-before-authority-and-delivery-trials" tabindex="-1">A5 Reconcile the skill study before authority and delivery trials <a class="header-anchor" href="#a5-reconcile-the-skill-study-before-authority-and-delivery-trials" aria-label="Permalink to &quot;A5 Reconcile the skill study before authority and delivery trials&quot;">​</a></h3><p><a href="#o1">O1</a> · <a href="#o9">O9</a> · <a href="#o14">O14</a> · <a href="#o16">O16</a> · <a href="#o17">O17</a> · <a href="#o18">O18</a> · <a href="#o19">O19</a> · <a href="#o20">O20</a> · <a href="#o21">O21</a> · <a href="#o22">O22</a> · <a href="#o29">O29</a> · <a href="#o30">O30</a></p><p>November 19 A1/O1 was independently tested and published yesterday; today&#39;s archive reconciliation adds no experiment count. O2–O6/live skill remain incomplete. A2/A3/A4 stay next-stage candidates, and A5 validation/A6 replay/A7 full app trials remain pending, not abandoned or silently closed. Paperclip raises main-radar identity/responsibility/recovery attention; Orca raises second-circle mobile/Bots attention; CrewAI is a framework delivery-semantics comparison. Separate releases, source, flags and device acceptance. No installations/exhaustive license review; zero new experiments/articles/formal reviews/development assignments today.</p><h2 id="disposition-synthesis-and-dual-source-coverage" tabindex="-1">Disposition, synthesis and dual-source coverage <a class="header-anchor" href="#disposition-synthesis-and-dual-source-coverage" aria-label="Permalink to &quot;Disposition, synthesis and dual-source coverage&quot;">​</a></h2><p>Compare event→principal authority→execution→artifact/evidence→acceptance without moving Runtime, scheduling, identity or storage directly into the FCoP core. New topics remain unverified; yesterday’s bounded skill experiment does not close every old item. No experiments rerun, new articles/reviews/development tasks or external comments today; no local defect inferred without evidence.</p><p>GitHub covered commits, Issues/PR and releases on 88 original entries with pagination, selected PRs, merged MCP text and yesterday’s experiment report. Of 264 source/type checks, 228 completed, 33 retain pagination gaps and three TSA endpoints returned 404. Only complete queries advance baselines. Superset follows the same-ID redirect to ParadevAI/Paradev without Registry replacement or closing historical gaps. Large release queries that failed were retried smaller; actual pagination limits remain recorded.</p><p>Second-type checks opened GitHub changelog, Cursor changelog and the official MCP blog plus selected official/author searches; no separately qualifying new announcement is not exhaustive social coverage. Final MCP status is established by the original GitHub version; two GitHub URLs are not two source types. Exhaustive 47-person X/replies, papers/Discussions and installation/license/commercial checks remain incomplete, including inherited author-page and Orca-license gaps. Governance relationships remain bounded; Mansura’s project is not the official AGENTSAFE artifact. Chinese uses 赵越.</p><p>Only the two daily sources and two indices change, not research/runtime/**, business lifecycle, entry components or layout. GitHub writes/readback precede separate build/publish/live homepage-click receipts; no premature website-success claim.</p>',157)])])}const m=a(i,[["render",s]]);export{u as __pageData,m as default};
